@'
import subprocess,time
from pywinauto import Desktop
def until(fn,label,seconds=20):
    end=time.monotonic()+seconds
    while time.monotonic()<end:
        try:
            v=fn()
            if v:return v
        except Exception:pass
        time.sleep(.25)
    raise AssertionError(label)
for x in Desktop(backend="uia").windows():
    if x.window_text() in ("설정","Settings"):
        try:x.close()
        except Exception:pass
time.sleep(2)
subprocess.Popen(["cmd","/c","start","","ms-settings:"])
def settings():
    ws=[x for x in Desktop(backend="uia").windows() if x.window_text() in ("설정","Settings")]
    return ws[-1] if ws else None
win=until(settings,"Settings window missing")
acc=win.child_window(title="접근성",control_type="ListItem")
if not acc.exists(timeout=1):
    acc=win.child_window(title="Accessibility",control_type="ListItem")
print("ACCESS_ITEM_EXISTS",acc.exists(timeout=1),flush=True)
acc.click_input()
time.sleep(2)
matches=[]
for e in win.descendants():
    name=(e.element_info.name or "").strip()
    if name in ("대비 테마","Contrast themes"):
        matches.append((e.element_info.control_type,name,e.element_info.automation_id,e.handle))
print("CONTRAST_MATCHES",matches,flush=True)
for e in win.descendants():
    info=e.element_info
    if info.control_type in ("Button","Group","ListItem") and (info.name or "").strip():
        if "대비" in (info.name or "") or "contrast" in (info.name or "").lower():
            print("CONTRAST_CANDIDATE",info.control_type,repr(info.name),repr(info.automation_id),flush=True)
try:win.close()
except Exception:pass
print("HIGH_CONTRAST_SETTINGS_NAVIGATION_PROBE_PASS",flush=True)

'@ | Set-Content -LiteralPath $probe -Encoding UTF8
& python -X utf8 $probe
$code=$LASTEXITCODE
Remove-Item $probe -Force -ErrorAction SilentlyContinue
if($code -ne 0){throw "Settings navigation probe failed"}
Write-Host "HIGH_CONTRAST_SETTINGS_NAVIGATION_CONTROL_PASS"
